record.field:
model.refresh_dashboard()
# Send email alert if enabled
config = env['ir.config_parameter'].sudo()
if config.get_param('negative_stock_control.cron_email', 'True') == 'True':
    negative_records = model.search([('qty_on_hand', '<', 0)])
    if negative_records:
        template = env.ref('negative_stock_control.mail_template_negative_stock_alert', raise_if_not_found=False)
        if template:
            admin_email = config.get_param('negative_stock_control.admin_email')
            if admin_email:
                template.with_context(negative_records=negative_records).send_mail(
                    negative_records[0].id, force_send=True,
                    email_values={'email_to': admin_email}
                )
